function ata(owner,mint,tokenProgram){return PublicKey.findProgramAddressSync([new PublicKey(owner).toBuffer(),new PublicKey(tokenProgram).toBuffer(),new PublicKey(mint).toBuffer()],new PublicKey(ATA_PROGRAM))[0].toString()}
function usdgAta(wallet){return ata(wallet,KAMINO.underlyingMint,TOKEN_2022)}
