export function buildArmedVariants({wallet,nonces,shares,baseInstructions,luts=[],fees}){const owner=new PublicKey(wallet),amount=exactShareBytes(shares,6);if(!Array.isArray(fees)||fees.length!==3||!Array.isArray(nonces)||nonces.length!==3||new Set(nonces.map(n=>n.nonceAccount)).size!==3||fees.some(fee=>!Number.isInteger(fee)||fee<0||fee>1000000))throw new Error("invalid_fee_ladder");const instructions=baseInstructions.filter(ix=>!(ix.programId.toString()===TOKEN_PROGRAM&&Buffer.from(ix.data).toString("hex")==="09")).map(ix=>{const data=Buffer.from(ix.data);if(ix.programId.toString()===FARMS_PROGRAM&&data.subarray(0,8).toString("hex")==="5a5f6b2acd7c32e1"){if(data.length<24)throw new Error("invalid_farm_unstake_instruction");amount.farmAmount.copy(data,8);return new TransactionInstruction({...ix,data})}if(ix.programId.toString()===KAMINO.program&&data.subarray(0,8).toString("hex")==="1383709baadc2239"){if(data.length!==16)throw new Error("invalid_kvault_withdraw_instruction");amount.vaultAmount.copy(data,8);return new TransactionInstruction({...ix,data})}return ix});if(!instructions.some(ix=>ix.programId.toString()===FARMS_PROGRAM&&Buffer.from(ix.data).subarray(0,8).toString("hex")==="5a5f6b2acd7c32e1")||!instructions.some(ix=>ix.programId.toString()===KAMINO.program&&Buffer.from(ix.data).subarray(0,8).toString("hex")==="1383709baadc2239"))throw new Error("required_withdraw_instructions_missing");return fees.map((priorityMicroLamports,index)=>{const nonce=nonces[index],ordered=[SystemProgram.nonceAdvance({noncePubkey:new PublicKey(nonce.nonceAccount),authorizedPubkey:owner}),ComputeBudgetProgram.setComputeUnitLimit({units:450000}),ComputeBudgetProgram.setComputeUnitPrice({microLamports:priorityMicroLamports}),...instructions];const tx=new VersionedTransaction(new TransactionMessage({payerKey:owner,recentBlockhash:nonce.nonceValue,instructions:ordered}).compileToV0Message(luts));return{transaction:Buffer.from(tx.serialize()).toString("base64"),priorityMicroLamports,nonceAccount:nonce.nonceAccount,nonceValue:nonce.nonceValue,shares:String(shares)}})}
async function validateEvacuationTransaction(fetchImpl,rpcUrl,encoded,wallet){const tx=VersionedTransaction.deserialize(Buffer.from(encoded,"base64"));if(tx.message.header.numRequiredSignatures!==1||tx.message.staticAccountKeys[0]?.toString()!==wallet)throw new Error("unexpected_transaction_signers");const luts=await lookupAccounts(fetchImpl,rpcUrl,tx.message);const message=TransactionMessage.decompile(tx.message,{addressLookupTableAccounts:luts}),ixs=message.instructions;for(const ix of ixs){const program=ix.programId.toString();if(!ALLOWED_EVACUATION_PROGRAMS.has(program))throw new Error(`unexpected_program:${program}`);if(ix.keys.some(key=>key.isSigner&&key.pubkey.toString()!==wallet))throw new Error("unexpected_instruction_signer")}
 const programs=ixs.map(ix=>ix.programId.toString()),offset=programs[0]===COMPUTE_PROGRAM?1:0,expected=[ATA_PROGRAM,FARMS_PROGRAM,FARMS_PROGRAM,ATA_PROGRAM,KAMINO.program,TOKEN_PROGRAM];if(programs.length!==expected.length+offset||expected.some((program,index)=>programs[index+offset]!==program))throw new Error("unexpected_instruction_sequence");if(offset){const data=Buffer.from(ixs[0].data);if(data.length!==9||data[0]!==3||data.readBigUInt64LE(1)>1000000n)throw new Error("unexpected_priority_fee_instruction")}
 const shareAta=sharesAta(wallet),destination=usdgAta(wallet),shareCreate=ixs[offset],unstake=ixs[offset+1],farmWithdraw=ixs[offset+2],destinationCreate=ixs[offset+3],withdraw=ixs[offset+4],close=ixs[offset+5];const keys=ix=>ix.keys.map(key=>key.pubkey.toString()),hex=ix=>Buffer.from(ix.data).toString("hex");
 if(hex(shareCreate)!=="01"||keys(shareCreate)[0]!==wallet||keys(shareCreate)[1]!==shareAta||keys(shareCreate)[2]!==wallet||keys(shareCreate)[3]!==KAMINO.sharesMint||keys(shareCreate)[5]!==TOKEN_PROGRAM)throw new Error("unexpected_share_ata_instruction");
 if(!hex(unstake).startsWith("5a5f6b2acd7c32e1")||keys(unstake)[0]!==wallet||!hex(farmWithdraw).startsWith("2466bb31dc248443")||keys(farmWithdraw)[0]!==wallet||keys(farmWithdraw)[3]!==shareAta)throw new Error("unexpected_farm_instruction");
 if(hex(destinationCreate)!=="01"||keys(destinationCreate)[0]!==wallet||keys(destinationCreate)[1]!==destination||keys(destinationCreate)[2]!==wallet||keys(destinationCreate)[3]!==KAMINO.underlyingMint||keys(destinationCreate)[5]!==TOKEN_2022)throw new Error("unexpected_destination_ata_instruction");
 const withdrawKeys=keys(withdraw);if(hex(withdraw)!=="1383709baadc2239ffffffffffffffff"||withdrawKeys[0]!==wallet||withdrawKeys[1]!==KAMINO.vault||withdrawKeys[5]!==destination||withdrawKeys[6]!==KAMINO.underlyingMint||withdrawKeys[7]!==shareAta||withdrawKeys[8]!==KAMINO.sharesMint)throw new Error("unexpected_kvault_withdraw_instruction");
 if(hex(close)!=="09"||keys(close)[0]!==shareAta||keys(close)[1]!==wallet||keys(close)[2]!==wallet)throw new Error("unexpected_close_instruction");return{tx,luts}}

export async function prepareEvacuation({wallet,shares,priorityFeeCap=0,fetchImpl=fetch,rpcUrl=process.env.SOLANA_RPC_URL||"https://api.mainnet-beta.solana.com",kaminoApiUrl=process.env.KAMINO_API_URL||"https://api.kamino.finance"}){if(!validateSolanaAddress(wallet))throw new Error("invalid_wallet");if(!/^\d+(\.\d+)?$/.test(String(shares))||Number(shares)<=0)throw new Error("invalid_shares");const cap=Math.max(0,Math.min(1000000,Math.trunc(Number(priorityFeeCap)||0)));let priorityMicroLamports=0;if(cap>0){const recent=await rpc(fetchImpl,rpcUrl,"getRecentPrioritizationFees",[]);const fees=recent.map(row=>Number(row.prioritizationFee)||0).filter(value=>value>0).sort((a,b)=>a-b);priorityMicroLamports=Math.min(cap,fees.length?fees[Math.floor((fees.length-1)*.75)]:cap)}const response=await fetchImpl(`${kaminoApiUrl}/ktx/kvault/withdraw`,{method:"POST",headers:{"content-type":"application/json","user-agent":"kelvara-kamino-monitor/0.1"},body:JSON.stringify({wallet,kvault:KAMINO.vault,amount:String(shares)})});const body=await response.json();if(!response.ok||!body.transaction)throw new Error(`kamino_withdraw_http_${response.status}:${body.message||"unavailable"}`);let {tx,luts}=await validateEvacuationTransaction(fetchImpl,rpcUrl,body.transaction,wallet);if(priorityMicroLamports>0){const decompiled=TransactionMessage.decompile(tx.message,{addressLookupTableAccounts:luts});decompiled.instructions.unshift(ComputeBudgetProgram.setComputeUnitPrice({microLamports:priorityMicroLamports}));const latest=await rpc(fetchImpl,rpcUrl,"getLatestBlockhash",[{commitment:"confirmed"}]);decompiled.recentBlockhash=latest.value.blockhash;tx=new VersionedTransaction(decompiled.compileToV0Message(luts));await validateEvacuationTransaction(fetchImpl,rpcUrl,Buffer.from(tx.serialize()).toString("base64"),wallet)}const encoded=Buffer.from(tx.serialize()).toString("base64");const simulation=await rpc(fetchImpl,rpcUrl,"simulateTransaction",[encoded,{encoding:"base64",sigVerify:false,replaceRecentBlockhash:true,commitment:"confirmed"}]);const fee=await rpc(fetchImpl,rpcUrl,"getFeeForMessage",[Buffer.from(tx.message.serialize()).toString("base64"),{commitment:"confirmed"}]);return{transaction:encoded,wallet,destinationOwner:wallet,destinationTokenAccount:usdgAta(wallet),asset:KAMINO.asset,shares:String(shares),priorityFeeCap:cap,priorityMicroLamports,baseFeeLamports:fee.value,simulation:{ok:simulation.value.err===null,error:simulation.value.err,unitsConsumed:simulation.value.unitsConsumed??null,logs:(simulation.value.logs||[]).slice(-8)},programs:[KAMINO.program,FARMS_PROGRAM],note:"Share redemption has no swap slippage setting. Output depends on the vault share exchange rate at execution."}}
async function prepareNonceSetup(wallet,nonceAccounts,{fetchImpl=fetch,rpcUrl=process.env.SOLANA_RPC_URL||"https://api.mainnet-beta.solana.com"}={}){if(!validateSolanaAddress(wallet)||!Array.isArray(nonceAccounts)||nonceAccounts.length!==3||new Set(nonceAccounts).size!==3)throw new Error("invalid_nonce_accounts");const owner=new PublicKey(wallet),rent=await rpc(fetchImpl,rpcUrl,"getMinimumBalanceForRentExemption",[NONCE_ACCOUNT_LENGTH]),latest=await rpc(fetchImpl,rpcUrl,"getLatestBlockhash",[{commitment:"confirmed"}]),tx=new Transaction({feePayer:owner,recentBlockhash:latest.value.blockhash});for(const value of nonceAccounts){const nonce=new PublicKey(value);tx.add(SystemProgram.createAccount({fromPubkey:owner,newAccountPubkey:nonce,lamports:rent,space:NONCE_ACCOUNT_LENGTH,programId:SystemProgram.programId}),SystemProgram.nonceInitialize({noncePubkey:nonce,authorizedPubkey:owner}))}return{transaction:tx.serialize({requireAllSignatures:false,verifySignatures:false}).toString("base64"),nonceAccounts,rentPerAccount:rent,totalRent:rent*3,lastValidBlockHeight:latest.value.lastValidBlockHeight}}
function validateNonceSetup(encoded,wallet,nonceAccounts,expectedRent){const tx=Transaction.from(Buffer.from(encoded,"base64"));if(tx.feePayer?.toString()!==wallet||tx.instructions.length!==6||tx.signatures.length!==4)throw new Error("invalid_nonce_setup");for(let index=0;index<3;index++){const create=SystemInstruction.decodeCreateAccount(tx.instructions[index*2]),initialize=SystemInstruction.decodeNonceInitialize(tx.instructions[index*2+1]);if(create.fromPubkey.toString()!==wallet||create.newAccountPubkey.toString()!==nonceAccounts[index]||create.lamports!==expectedRent||create.space!==NONCE_ACCOUNT_LENGTH||create.programId.toString()!==SystemProgram.programId.toString()||initialize.noncePubkey.toString()!==nonceAccounts[index]||initialize.authorizedPubkey.toString()!==wallet)throw new Error("invalid_nonce_setup")};if(tx.signatures.some(item=>!item.signature))throw new Error("nonce_setup_not_fully_signed");return tx}
async function nonceState(fetchImpl,rpcUrl,nonceAccount){const result=await rpc(fetchImpl,rpcUrl,"getAccountInfo",[nonceAccount,{encoding:"base64",commitment:"confirmed"}]);if(!result.value||result.value.owner!==SystemProgram.programId.toString())throw new Error("nonce_account_unavailable");const decoded=NonceAccount.fromAccountData(Buffer.from(result.value.data[0],"base64"));return{nonce:decoded.nonce,authority:decoded.authorizedPubkey.toString(),lamports:result.value.lamports}}
export async function recoverPendingNonceSetup(wallet,{fetchImpl=fetch,rpcUrl=process.env.SOLANA_RPC_URL||"https://api.mainnet-beta.solana.com",limit=50}={}){if(!validateSolanaAddress(wallet))throw new Error("invalid_wallet");const signatures=await rpc(fetchImpl,rpcUrl,"getSignaturesForAddress",[wallet,{limit,commitment:"confirmed"}]);for(const entry of signatures){if(entry.err)continue;const result=await rpc(fetchImpl,rpcUrl,"getTransaction",[entry.signature,{encoding:"jsonParsed",maxSupportedTransactionVersion:0,commitment:"confirmed"}]);const message=result?.transaction?.message,instructions=message?.instructions;if(result?.meta?.err||!Array.isArray(instructions)||instructions.length!==6||result.transaction.signatures?.length!==4)continue;const nonceAccounts=[];let valid=true;for(let index=0;index<3;index++){const create=instructions[index*2]?.parsed,initialize=instructions[index*2+1]?.parsed,created=create?.info?.newAccount;if(create?.type!=="createAccount"||create.info.source!==wallet||create.info.owner!==SystemProgram.programId.toString()||create.info.space!==NONCE_ACCOUNT_LENGTH||initialize?.type!=="initializeNonce"||initialize.info.nonceAccount!==created||initialize.info.nonceAuthority!==wallet){valid=false;break}nonceAccounts.push(created)}if(!valid||new Set(nonceAccounts).size!==3)continue;try{for(const account of nonceAccounts){const state=await nonceState(fetchImpl,rpcUrl,account);if(state.authority!==wallet)throw new Error("nonce_authority_mismatch")}return{wallet,nonceAccounts,setupSignature:entry.signature,setupConfirmed:true}}catch{continue}}return null}
export function buildNonceReclaimTransaction({wallet,nonceAccounts,balances,blockhash}){if(!validateSolanaAddress(wallet)||!Array.isArray(nonceAccounts)||nonceAccounts.length!==3||new Set(nonceAccounts).size!==3||!Array.isArray(balances)||balances.length!==3||balances.some(value=>!Number.isSafeInteger(value)||value<=0))throw new Error("invalid_reclaim_accounts");const owner=new PublicKey(wallet),tx=new Transaction({feePayer:owner,recentBlockhash:blockhash});nonceAccounts.forEach((nonceAccount,index)=>tx.add(SystemProgram.nonceWithdraw({noncePubkey:new PublicKey(nonceAccount),authorizedPubkey:owner,toPubkey:owner,lamports:balances[index]})));return tx.serialize({requireAllSignatures:false,verifySignatures:false}).toString("base64")}
export function validateNonceReclaimTransaction(encoded,wallet,nonceAccounts,balances){const tx=Transaction.from(Buffer.from(encoded,"base64")),allowed=new Map(nonceAccounts.map((account,index)=>[account,balances[index]])),closed=[];for(const ix of tx.instructions){try{const decoded=SystemInstruction.decodeNonceWithdraw(ix),account=decoded.noncePubkey.toString();if(decoded.authorizedPubkey.toString()!==wallet||decoded.toPubkey.toString()!==wallet||decoded.lamports!==allowed.get(account))throw new Error();closed.push(account)}catch{throw new Error("invalid_reclaim_transaction")}}if(tx.feePayer?.toString()!==wallet||closed.length!==allowed.size||new Set(closed).size!==allowed.size||tx.signatures.some(item=>!item.signature))throw new Error("invalid_reclaim_transaction");return closed}
async function kaminoBase(fetchImpl,rpcUrl,kaminoApiUrl,wallet,shares){const response=await fetchImpl(`${kaminoApiUrl}/ktx/kvault/withdraw`,{method:"POST",headers:{"content-type":"application/json","user-agent":"kelvara-kamino-monitor/0.1"},body:JSON.stringify({wallet,kvault:KAMINO.vault,amount:String(shares)})}),body=await response.json();if(!response.ok||!body.transaction)throw new Error(`kamino_withdraw_http_${response.status}`);const {tx,luts}=await validateEvacuationTransaction(fetchImpl,rpcUrl,body.transaction,wallet),message=TransactionMessage.decompile(tx.message,{addressLookupTableAccounts:luts});return{baseInstructions:message.instructions.filter(ix=>ix.programId.toString()!==COMPUTE_PROGRAM),luts}}
