 let last=null,lastError=null,controlLast=null,controlLastError=null,timer=null;const controlIncidents=new Map(),rateWindows=new Map();async function poll(){try{const next=await inspector.inspectControlPlane();const previous=controlLast?.adminRights;controlLast=next;controlLastError=null;if(previous&&next.adminRights?.authorities){for(const incident of evaluateAdminRollovers({previous,current:next.adminRights,announcements:announcementRegistry.announcements,registryFresh:announcementRegistry.fresh})){if(!controlIncidents.has(incident.dedupKey))controlIncidents.set(incident.dedupKey,incident)}}}catch(error){controlLastError={message:error.message,observedAt:new Date().toISOString()}}if(!monitoredWallet)return;try{last=await inspector.inspect(monitoredWallet);lastError=null}catch(error){lastError={message:error.message,observedAt:new Date().toISOString()}}}
